package org.tomdang.bootstrap;
import org.tomdang.TomBlock;import org.tomdang.critter.configuration.*;import org.tomdang.critter.definition.*;import org.tomdang.critter.ecology.*;import org.tomdang.critter.journal.*;import org.tomdang.critter.presentation.GlimmerflyEncounterBehavior;import org.tomdang.critter.progression.CritterProgressionService;import org.tomdang.critter.runtime.CritterRuntimeService;import org.tomdang.customitemframework.*;import org.tomdang.gameplay.event.GameplayEventBus;import org.tomdang.player.*;import org.tomdang.player.playeractionbar.PlayerActionBarService;import org.tomdang.player.playerdata.PlayerProfileRepository;import org.tomdang.player.skill.*;import javax.sql.DataSource;
public final class CritterBootstrap implements AutoCloseable{
	private final CritterRegistry definitions=new CritterRegistry();private final CritterRuntimeService runtime;private final CritterJournalService journal;private final CritterProgressionService progression;private final GlimmerflyEncounterBehavior glimmerfly;private final CritterEcologyService ecology=new CritterEcologyService();
	public CritterBootstrap(TomBlock plugin,DataSource dataSource,GameplayEventBus events,EncounterBootstrap encounters,PlayerProfileService profiles,PlayerProfileRepository profileRepository,PlayerActionBarService actionBar,CustomItemRegistry items,CustomItemStackFactory stacks){var loader=new CritterConfigurationLoader();for(String resource:new CritterResourceDiscovery().discover(plugin.getClass()))try(var input=plugin.getResource(resource)){definitions.register(loader.load(input));}catch(java.io.IOException exception){throw new IllegalStateException("Could not load "+resource,exception);}definitions.seal();CritterJournalRepository journalRepository=dataSource==null?new InMemoryCritterJournalRepository():new PostgresCritterJournalRepository(dataSource);journal=new CritterJournalService(journalRepository);runtime=new CritterRuntimeService(definitions,events);progression=new CritterProgressionService(events,definitions,journal,profiles,profileRepository,new SkillProgressionService(),new SkillProgressPresenter(actionBar),items,stacks);glimmerfly=new GlimmerflyEncounterBehavior(plugin,runtime,encounters::runtime);encounters.behaviors().register("GLIMMERFLY_HUNT",glimmerfly);plugin.getLogger().info("Loaded "+definitions.all().size()+" critter definitions.");}
	public CritterRegistry definitions(){return definitions;}public CritterRuntimeService runtime(){return runtime;}public CritterJournalService journal(){return journal;}public CritterEcologyService ecology(){return ecology;}
	@Override public void close(){glimmerfly.close();progression.close();}
}
